INSERT INTO breath_manager_v5.bm5_external_checks (check_id, title, description, status) VALUES ('EXT01', 'NHLBI How the Lungs Work — What Breathing Does for the Body', '換気・肺胞のガス交換・ヘモグロビンによる酸素運搬の基礎を照合。', 'official_health_information') ON CONFLICT (check_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_external_checks (check_id, title, description, status) VALUES ('EXT02', 'NHLBI How Your Body Controls Breathing', '呼吸調節はCO₂だけのスイッチではないことを照合。', 'official_health_information') ON CONFLICT (check_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_external_checks (check_id, title, description, status) VALUES ('EXT03', 'NIGMS Science Snippet ATP’s Amazing Power', 'ATPの役割を照合。1日で体重相当量が回転するとの概説を確認し、教材の毎分2〜3kgとは整合しない点を記録。個人の産生量の確定はしていない。', 'official_science_information') ON CONFLICT (check_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_external_checks (check_id, title, description, status) VALUES ('EXT04', 'Common Yoga Protocol 教材が引用するインド政府公開PDF', '当該版の目次・カパラバティ・交互鼻呼吸・ブラーマリーの記載を確認。シータリーの掲載を確認できず。治療効果の裏付け評価は行っていない。', 'official_protocol') ON CONFLICT (check_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_external_checks (check_id, title, description, status) VALUES ('EXT05', 'FDA: Pulse Oximeter Basics', 'SpO₂の推定値としての性質と測定限界のみ。教材の区分表は承認しない。', NULL) ON CONFLICT (check_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_external_checks (check_id, title, description, status) VALUES ('EXT06', 'NHLBI: Sleep Apnea', '睡眠時無呼吸の基本定義のみ。', NULL) ON CONFLICT (check_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_external_checks (check_id, title, description, status) VALUES ('EXT07', 'NHLBI: Sleep Apnea Symptoms', '呼吸停止、いびき、日中の眠気等の相談につながる症状。', NULL) ON CONFLICT (check_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_external_checks (check_id, title, description, status) VALUES ('EXT08', 'NHLBI: Sleep Phases and Stages', 'NREMの段階数のみを修正提案に反映。呼吸法の睡眠改善効果は検証しない。', NULL) ON CONFLICT (check_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_external_checks (check_id, title, description, status) VALUES ('EXT09', 'CDC: About Sleep', '生活習慣に関する原稿の参照先を特定。個別治療や呼吸法の効能は対象外。', NULL) ON CONFLICT (check_id) DO NOTHING;